    def add(project, action, text, at, actor=None):
        Activity.objects.create(project=project, action=action, text=text[:500], at=at, actor=actor)

    for p in Project.objects.all():
        add(p, "created", f"Project opened: {p.name}", p.created_at)
        for item in p.scope_items.all():
            what = f"asset {item.device.asset_code}" if item.device_id else f"item x{item.quantity}"
            add(p, "scope", f"Scope: {what} added", item.created_at)
